/// A complete local value, not a firmware pointer. Hidden fields survive copy-back.
/// Methods conservatively require mutable values; copies do not share Lua-style identity.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct MissionItem {
    pub param1: f32,
    pub param2: f32,
    pub param3: f32,
    pub param4: f32,
    pub x: i32,
    pub y: i32,
    pub z: f32,
    pub seq: u16,
    pub command: u16,
    target_system: u8,
    target_component: u8,
    pub frame: u8,
    pub current: u8,
    autocontinue: u8,
    mission_type: u8,
}

impl MissionItem {
    pub(crate) fn encode(&self) -> [u8; 38] {
        let mut bytes = [0u8; 38];
        bytes[0..4].copy_from_slice(&self.param1.to_le_bytes());
        bytes[4..8].copy_from_slice(&self.param2.to_le_bytes());
        bytes[8..12].copy_from_slice(&self.param3.to_le_bytes());
        bytes[12..16].copy_from_slice(&self.param4.to_le_bytes());
        bytes[16..20].copy_from_slice(&self.x.to_le_bytes());
        bytes[20..24].copy_from_slice(&self.y.to_le_bytes());
        bytes[24..28].copy_from_slice(&self.z.to_le_bytes());
        bytes[28..30].copy_from_slice(&self.seq.to_le_bytes());
        bytes[30..32].copy_from_slice(&self.command.to_le_bytes());
        bytes[32..33].copy_from_slice(&self.target_system.to_le_bytes());
        bytes[33..34].copy_from_slice(&self.target_component.to_le_bytes());
        bytes[34..35].copy_from_slice(&self.frame.to_le_bytes());
        bytes[35..36].copy_from_slice(&self.current.to_le_bytes());
        bytes[36..37].copy_from_slice(&self.autocontinue.to_le_bytes());
        bytes[37..38].copy_from_slice(&self.mission_type.to_le_bytes());
        bytes
    }
    pub(crate) fn decode(bytes: &[u8]) -> Self {
        Self {
            param1: f32::from_le_bytes(bytes[0..4].try_into().unwrap()),
            param2: f32::from_le_bytes(bytes[4..8].try_into().unwrap()),
            param3: f32::from_le_bytes(bytes[8..12].try_into().unwrap()),
            param4: f32::from_le_bytes(bytes[12..16].try_into().unwrap()),
            x: i32::from_le_bytes(bytes[16..20].try_into().unwrap()),
            y: i32::from_le_bytes(bytes[20..24].try_into().unwrap()),
            z: f32::from_le_bytes(bytes[24..28].try_into().unwrap()),
            seq: u16::from_le_bytes(bytes[28..30].try_into().unwrap()),
            command: u16::from_le_bytes(bytes[30..32].try_into().unwrap()),
            target_system: u8::from_le_bytes(bytes[32..33].try_into().unwrap()),
            target_component: u8::from_le_bytes(bytes[33..34].try_into().unwrap()),
            frame: u8::from_le_bytes(bytes[34..35].try_into().unwrap()),
            current: u8::from_le_bytes(bytes[35..36].try_into().unwrap()),
            autocontinue: u8::from_le_bytes(bytes[36..37].try_into().unwrap()),
            mission_type: u8::from_le_bytes(bytes[37..38].try_into().unwrap()),
        }
    }

}

